<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import GovernanceListFrame from './GovernanceListFrame.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import FeedbackReviewPanel from './FeedbackReviewPanel.vue';import OperationsRecovery from './OperationsRecovery.vue';import {useGovernanceList} from './useGovernanceList';import {localTime,stateLabels,usageLabels,type VoicePage,type VoiceDetail} from './workbench-types';import './governance.css';
const props=withDefaults(defineProps<{personal?:boolean}>(),{personal:false}),app=useApplication(),ops=app.operationsCommands,route=useRoute(),router=useRouter(),list=useGovernanceList<VoicePage>(props.personal?'my-voiceprints':'voiceprints');
const drawer=ref<'detail'|'enroll'|null>(null),detail=ref<VoiceDetail|null>(null),reason=ref(''),error=ref(''),notice=ref(''),busy=ref(false),decision=ref('APPROVED'),sample=ref<File|null>(null),consent=ref(''),days=ref(30),agreed=ref(false);let epoch=0;
const actor=()=>app.session.current.value?.actor.enterpriseId??null,locked=computed(()=>busy.value||ops.pending.value||!ops.available.value),reviewable=computed(()=>!!detail.value&&!props.personal&&detail.value.subjectId!==actor()&&detail.value.applicantId!==actor());
function fail(cause:unknown){error.value=cause instanceof Error?cause.message:'声纹操作尚未确认。';}
async function open(id:string){const turn=++epoch;drawer.value='detail';detail.value=null;reason.value='';error.value='';try{const data=await ops.read<VoiceDetail>('/api/v1/operations/voiceprints/'+id);if(turn===epoch){detail.value=data;await router.replace({query:{...route.query,selected:id}});}}catch(cause){if(turn===epoch)fail(cause);}}
function close(){if(busy.value)return;epoch++;drawer.value=null;detail.value=null;reason.value='';sample.value=null;consent.value='';agreed.value=false;void router.replace({query:{...route.query,selected:undefined}});}
async function action(operation:()=>Promise<unknown>,message:string){if(locked.value)return;busy.value=true;error.value='';try{await operation();notice.value=message;drawer.value=null;detail.value=null;sample.value=null;consent.value='';agreed.value=false;await list.load();await router.replace({query:{...route.query,selected:undefined}});}catch(cause){fail(cause);}finally{busy.value=false;}}
function review(){const d=detail.value;if(!d)return;return action(()=>ops.submit(`/api/v1/operations/voiceprints/${d.id}/review`,{expectedRevisionToken:d.revisionToken,decision:decision.value,reason:reason.value}),'审核结果已记录。');}
function revoke(){const d=detail.value;if(!d)return;return action(()=>ops.submit(`/api/v1/operations/voiceprints/${d.id}/revocation`,{expectedRevisionToken:d.revisionToken,reason:reason.value}),'授权已撤销，后续匹配将排除该声纹。');}
function enroll(){return action(async()=>{const file=sample.value,who=actor(),turn=epoch;if(!file||file.size<96044||file.size>960044)throw Error('请选择 3–30 秒的 16kHz 单声道、16 位 WAV 文件。');if(!agreed.value||!consent.value.trim()||!Number.isInteger(days.value)||days.value<1||days.value>365)throw Error('请填写同意凭据、有效期，并明确同意用途。');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));if(turn!==epoch||who!==actor())throw new DOMException('Identity changed','AbortError');return ops.submit('/api/v1/operations/voiceprints',{consentReference:consent.value,expiresAt:new Date(Date.now()+days.value*86400000).toISOString(),wavBase64:btoa(binary)});},'本人声纹已提交，等待其他管理员审核。');}
watch(()=>route.query.selected,id=>{if(typeof id==='string'&&detail.value?.id!==id)void open(id);else if(typeof id!=='string'&&drawer.value==='detail'){epoch++;drawer.value=null;detail.value=null;}},{immediate:true});
watch([actor,()=>ops.available.value],()=>{epoch++;drawer.value=null;detail.value=null;sample.value=null;consent.value='';reason.value='';error.value='';agreed.value=false;},{flush:'sync'});onUnmounted(()=>epoch++);
</script>
<template><div :class="personal?'content governance-page':''"><OperationsRecovery v-if="personal"/><p v-if="notice" class="banner success" role="status">{{notice}}</p><GovernanceListFrame :title="personal?'我的声纹':'声纹管理'" :description="personal?'管理本人授权、有效期限与撤销记录。声纹只用于提供说话人候选。':'审核自助登记与会议采样，确保每份特征都有明确主体、用途和有效期限。'" :counts="list.page.value?.counts??{}" :total="list.page.value?.total??null" :loading="list.loading.value" :error="list.error.value" v-model:query="list.query.value" :state="list.state()" :states="['PENDING','APPROVED','REJECTED','NEEDS_MORE','REVOKED']" :next-cursor="list.page.value?.nextCursor" :has-cursor="list.hasCursor()" @search="list.search" @filter="list.filter('state',$event)" @refresh="list.load" @next="list.next" @first="list.first"><template #actions><button v-if="personal" class="btn primary" :disabled="locked" @click="drawer='enroll';error=''">登记本人声纹</button><RouterLink v-else class="btn" to="/my/voiceprints">我的声纹授权</RouterLink></template><template #filters><select class="select" aria-label="声纹使用状态" :value="route.query.usage??''" @change="list.filter('usage',($event.target as HTMLSelectElement).value)"><option value="">全部使用状态</option><option v-for="key in ['EFFECTIVE','NOT_APPLIED','REVOKED','EXPIRED','DISABLED','INCOMPATIBLE','MATCHING_DISABLED']" :key="key" :value="key">{{usageLabels[key]}}</option></select><select class="select" aria-label="声纹模型版本" :value="route.query.model??''" @change="list.filter('model',($event.target as HTMLSelectElement).value)"><option value="">全部模型</option><option value="harness-fixture-embedding-v1">会议语音模型 v1</option><option value="harness-embed-v1">历史模型（需重新登记）</option></select><input class="input" type="date" aria-label="声纹登记起始日期" :value="route.query.from??''" @change="list.filter('from',($event.target as HTMLInputElement).value)"/></template><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>声纹主体</th><th>来源</th><th>审核 / 使用</th><th>有效期至</th><th>模型 / 时长</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.page.value?.items" :key="item.id"><td class="primary-cell"><button class="gov-link" @click="open(item.id)">{{item.subjectName}}</button><span class="sub-cell">{{item.subjectId}}</span></td><td>{{item.origin==='SELF'?'本人登记':'会议采样'}}<span class="sub-cell">{{item.origin==='MEETING'?'申请人：'+item.applicantId:'本人明确同意'}}</span></td><td><span class="gov-tag" :data-state="item.state">{{stateLabels[item.state]}}</span><span class="sub-cell">{{usageLabels[item.usageState]}}</span></td><td>{{localTime(item.expiresAt)}}</td><td>{{item.modelVersion}}<span class="sub-cell">{{(item.sampleCount/16000).toFixed(1)}} 秒</span></td><td><button class="gov-link" @click="open(item.id)">{{!personal&&item.state==='PENDING'?'查看并审核':'查看详情'}}</button></td></tr></tbody></table></div><div v-if="!list.page.value?.items.length" class="gov-empty"><Icon name="user" :size="32"/><h3>{{personal?'暂无本人声纹授权':'当前筛选下没有声纹记录'}}</h3><p>{{personal?'登记后需由其他管理员审核，随后按已发布的匹配规则提供候选。':'来自会议和个人的申请会统一进入此队列。'}}</p></div></GovernanceListFrame><p class="gov-disclosure">匹配候选须由会议编辑者人工确认。声纹识别结果不会增加会议访问权限。</p>
<GovernanceDrawer v-if="drawer==='detail'" title="声纹授权详情" wide :busy="busy||app.feedbackActions.busy.value" @close="close"><p v-if="error" class="gov-error" role="alert">{{error}}</p><template v-if="detail"><dl class="gov-definition"><dt>声纹主体</dt><dd>{{detail.subjectName}} · {{detail.subjectId}}</dd><dt>申请人</dt><dd>{{detail.applicantId}}</dd><dt>来源</dt><dd>{{detail.origin==='SELF'?'本人自助登记':'会议独立采样'}}</dd><dt>实际使用</dt><dd>{{usageLabels[detail.usageState]}}</dd><dt>有效期至</dt><dd>{{localTime(detail.expiresAt)}}</dd><dt>模型版本</dt><dd>{{detail.modelVersion}}</dd><dt>有效样本</dt><dd>{{(detail.sampleCount/16000).toFixed(1)}} 秒</dd></dl><FeedbackReviewPanel v-if="detail.origin==='MEETING'" :id="detail.id" :can-review="reviewable" @changed="list.load"/><template v-else><dl class="gov-definition"><dt>审核状态</dt><dd>{{stateLabels[detail.state]}}</dd><dt>处理意见</dt><dd>{{detail.reviewReason||'等待审核'}}</dd></dl><h3>授权历史</h3><ol class="gov-history"><li v-for="item in detail.history" :key="item.revisionToken"><b>{{stateLabels[item.state]}} · {{item.actorId}}</b><time>{{localTime(item.createdAt)}}</time><p>{{item.reason}}</p></li></ol><div v-if="reviewable&&detail.state==='PENDING'" class="gov-fields"><label>审核结论<select v-model="decision" class="select" :disabled="locked"><option value="APPROVED">通过</option><option value="REJECTED">驳回并要求重新登记</option></select></label><label>审核意见<textarea v-model="reason" class="textarea" maxlength="2048" :disabled="locked"/></label><button class="btn primary" :disabled="locked||!reason.trim()" @click="review">提交审核</button></div></template><div v-if="detail.subjectId===actor()&&detail.state!=='REVOKED'&&(detail.origin==='SELF'||detail.state==='APPROVED')" class="gov-fields"><div class="gov-note">撤销后立即停止后续匹配并清理保存的特征。已有会议中的人工命名会保留。</div><label>撤销原因<textarea v-model="reason" class="textarea" maxlength="2048" :disabled="locked"/></label><button class="btn danger" :disabled="locked||!reason.trim()" @click="revoke">撤销本人授权</button></div></template><p v-else-if="!error" role="status">正在读取授权详情…</p></GovernanceDrawer>
<GovernanceDrawer v-if="drawer==='enroll'" title="登记本人声纹" subtitle="明确同意用途后提交，由其他管理员审核。" wide :busy="busy" @close="close"><p v-if="error" class="gov-error" role="alert">{{error}}</p><div class="gov-fields"><label>本人语音样本<input type="file" accept=".wav,audio/wav" :disabled="locked" @change="sample=($event.target as HTMLInputElement).files?.[0]??null"/><span class="gov-muted">3–30 秒 · 16kHz 单声道 · 16 位 WAV · 清晰且仅包含本人声音</span></label><label>同意凭据或本人同意说明<textarea v-model="consent" class="textarea" maxlength="1024" :disabled="locked" placeholder="说明本人同意的记录或用途"/></label><label>有效天数<input v-model.number="days" class="input" type="number" min="1" max="365" :disabled="locked"/></label><label class="gov-check"><input v-model="agreed" type="checkbox" :disabled="locked"/>我同意在上述期限内将本人声纹用于说话人候选识别，知悉可随时撤销。</label></div><template #footer><button class="btn" :disabled="busy" @click="close">取消</button><button class="btn primary" :disabled="locked||!sample||!consent.trim()||!agreed" @click="enroll">提交声纹审核</button></template></GovernanceDrawer></div></template>
